#include "../../support/official.hpp"
#include "../support/diag_spectrum.hpp"
using namespace p3official;
struct Case{std::string mesh;size_t id;Real alpha,theta,c,rho;};
int main(int argc,char**argv){try{
 if(argc!=4)throw std::runtime_error("usage: diag_D1 config selected.tsv output_directory");gss::SlepcContext slepc;
 auto settings=load_settings(argv[1]);auto config=gss::YAMLConfig::load(argv[1]);auto study=ps::load_study_settings(argv[1]);study.random_mesh_seed=settings.mesh_seed;
 std::ifstream in(argv[2]);std::vector<Case> cases;Case q;while(in>>q.mesh>>q.id>>q.alpha>>q.theta>>q.c>>q.rho)cases.push_back(q);
 std::ofstream out(std::string(argv[3])+"/d1_cases.csv"),pairs(std::string(argv[3])+"/d1_eigenpairs.csv");out<<std::setprecision(17);pairs<<std::setprecision(17);
 out<<"mesh_family,case_id,rho_reference,rho,im_rel,gap,mu1_is_real,mu1_simple_proxy,kappa_mu1,nconv,iterations,reason";for(int k=1;k<=8;k++)out<<",mu_"<<k<<"_re,mu_"<<k<<"_im,abs_mu_"<<k;out<<'\n';pairs<<"mesh_family,case_id,rank,re,im,abs_mu,relative_residual\n";
 const vgt::gradients::polynomial::WLSQR2D method{vgt::gradients::WLSOptions2D{vgt::gradients::WLSWeighting2D::InverseDistanceSquared}};
 for(auto mesh:settings.mesh_families){auto mc=ps::make_mesh_config(config.mesh,mesh,settings.mesh_seed,settings.nominal_nx,settings.nominal_ny);gss::Fadeev cf{settings.calibration_alpha,settings.calibration_theta_degrees,Real{1}};auto ws=ps::make_workspace(mc,cf,study.jacobian_stencil_radius);auto bs=evaluate_base_source(ws,ws.exact,cf,method,config.solver.source_regularisation_delta,study);auto comp=make_compensator(ws,ws.exact,bs,Real{1});ModifiedSource src{ws,cf,method,config.solver.source_regularisation_delta,study,Real{1},comp};SourceJacobianAssembler jac{ws,method,config.solver.source_regularisation_delta,study,settings.source_derivative};auto vals=jac.values(ws.exact,src);auto b=sparse::to_csr(ws.jacobian_pattern,vals);spectral::MatrixFreePicardOperator op{ws.poisson.matrix,b};diag::Shell shell{op};
 size_t count=0;for(auto row:cases)if(row.mesh==mesh){auto local=study;local.alpha=row.alpha;local.theta_degrees=row.theta;gss::Fadeev f{row.alpha,row.theta,Real{1}};refresh_case_data(ws,f);auto base=evaluate_base_source(ws,ws.exact,f,method,config.solver.source_regularisation_delta,local);auto comp2=make_compensator(ws,ws.exact,base,row.c);ModifiedSource source{ws,f,method,config.solver.source_regularisation_delta,local,row.c,comp2};op.update_b_values(jac.values(ws.exact,source));auto s=diag::spectrum(shell.mat);double im=abs(s.pairs[0].mu.imag())/s.rho(),gap=s.pairs.size()>1?abs(s.pairs[1].mu)/s.rho():NAN;out<<mesh<<','<<row.id<<','<<row.rho<<','<<s.rho()<<','<<im<<','<<diag::number(gap)<<','<<(im<=1e-10)<<','<<(s.pairs.size()>1&&abs(s.pairs[0].mu-s.pairs[1].mu)/s.rho()>1e-8)<<','<<diag::number(s.kappa)<<','<<s.nconv<<','<<s.iterations<<','<<s.reason;for(size_t k=0;k<8;k++){if(k<s.pairs.size())out<<','<<s.pairs[k].mu.real()<<','<<s.pairs[k].mu.imag()<<','<<abs(s.pairs[k].mu);else out<<",NA,NA,NA";}out<<'\n';out.flush();for(size_t k=0;k<s.pairs.size();k++)pairs<<mesh<<','<<row.id<<','<<k+1<<','<<s.pairs[k].mu.real()<<','<<s.pairs[k].mu.imag()<<','<<abs(s.pairs[k].mu)<<','<<s.pairs[k].error<<'\n';pairs.flush();if(++count%100==0)std::cout<<mesh<<" completed "<<count<<std::endl;}
 }
 return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
